import{_ as a,c as t,a2 as s,o as l}from"./chunks/framework.CKGreiRV.js";const h=JSON.parse('{"title":"言語リファレンスについて","description":"","frontmatter":{},"headers":[],"relativePath":"resource/swift/aboutthelanguagereference.md","filePath":"resource/swift/aboutthelanguagereference.md","lastUpdated":1735910155000}'),i={name:"resource/swift/aboutthelanguagereference.md"};function r(n,e,o,c,p,d){return l(),t("div",null,e[0]||(e[0]=[s(`<h1 id="言語リファレンスについて" tabindex="-1">言語リファレンスについて <a class="header-anchor" href="#言語リファレンスについて" aria-label="Permalink to &quot;言語リファレンスについて&quot;">​</a></h1><p>形式文法で使用される表記法を読んでください。</p><p>この本のこの部分では、Swiftプログラミング言語の形式文法について説明します。ここで説明される文法は、パーサーやコンパイラを直接実装するためではなく、言語をより詳細に理解するのに役立つことを目的としています。</p><p>Swiftは比較的小さな言語です。これは、Swiftコードのほぼすべての場所に登場する多くの一般的な型、関数、演算子が、実際にはSwift標準ライブラリで定義されているためです。これらの型、関数、演算子はSwift言語自体の一部ではありませんが、本書のこの部分での説明やコード例で広く使用されています。</p><h2 id="文法の読み方" tabindex="-1">文法の読み方 <a class="header-anchor" href="#文法の読み方" aria-label="Permalink to &quot;文法の読み方&quot;">​</a></h2><p>Swiftプログラミング言語の形式文法を説明するために使用される表記法には、いくつかの規則があります：</p><ul><li>矢印（→）は文法の生成規則を示すために使用され、「次のように構成できる」と読むことができます。</li><li>構文カテゴリは<em>イタリック体のテキスト</em>で示され、文法生成規則の両側に現れます。</li><li>リテラルワードと句読点は<strong>太字の固定幅テキスト</strong>で示され、文法生成規則の右側にのみ現れます。</li><li>代替の文法生成規則は縦棒（|）で区切られます。代替の生成規則が長すぎて読みにくい場合は、新しい行で複数の文法生成規則に分割されます。</li><li>いくつかの場合において、通常のフォントのテキストを使用して、文法生成規則の右側を説明します。</li><li>オプションの構文カテゴリとリテラルは、末尾に疑問符 <code>?</code> を付けて示されます。</li></ul><p>例として、ゲッター・セッターブロックの文法は以下のように定義されています：</p><h3 id="ゲッター・セッターブロックの文法" tabindex="-1">ゲッター・セッターブロックの文法 <a class="header-anchor" href="#ゲッター・セッターブロックの文法" aria-label="Permalink to &quot;ゲッター・セッターブロックの文法&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>getter-setter-block → { getter-clause setter-clause? } | { setter-clause getter-clause }</span></span></code></pre></div><p>この定義は、ゲッター・セッターブロックが、中括弧で囲まれたゲッター句とオプションのセッター句で構成できること、または中括弧で囲まれたセッター句とゲッター句で構成できることを示しています。上記の文法生成規則は、代替規則を明示的に示した以下の2つの生成規則と同等です：</p><h3 id="ゲッター・セッターブロックの文法-1" tabindex="-1">ゲッター・セッターブロックの文法 <a class="header-anchor" href="#ゲッター・セッターブロックの文法-1" aria-label="Permalink to &quot;ゲッター・セッターブロックの文法&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>getter-setter-block → { getter-clause setter-clause? }</span></span>
<span class="line"><span>getter-setter-block → { setter-clause getter-clause }</span></span></code></pre></div>`,13)]))}const g=a(i,[["render",r]]);export{h as __pageData,g as default};
